using JMobile.Core;
using JMobile.Core.Execution;
using JMobile.Core.Loading;
using JMobile.Core.Model;
using JMobile.Runtime;
using JMobile.Runtime.Lang;

namespace JMobile.Tests;

/// <summary>
/// Runs compiled Java bytecode through the interpreter and compares the results against values a
/// real JVM produced.
/// </summary>
/// <remarks>
/// The expectations in <c>fixtures/expected.txt</c> were generated by running
/// <c>fixtures/java/Expected.java</c> on a real JVM, so these are conformance tests rather than
/// tests of what this implementation happens to do. Where the two disagree, the JVM is right.
/// </remarks>
public static class VmConformanceTests
{
    private static VirtualMachine? _vm;
    private static JavaThread? _thread;

    public static void Register()
    {
        Test.Suite("vm conformance");

        string fixtures = LocateFixtures();
        string expectedFile = Path.Combine(fixtures, "expected.txt");

        if (!File.Exists(expectedFile))
        {
            Test.Case("fixtures are present", () =>
                throw new AssertionException(
                    $"expected.txt was not found at {expectedFile}; run tools/build-fixtures.ps1"));
            return;
        }

        Dictionary<string, string> expected = ReadExpectations(expectedFile);

        // Every expectation becomes one test, so a single divergence names exactly which
        // language feature broke rather than failing one giant assertion.
        foreach (KeyValuePair<string, string> entry in expected)
        {
            string key = entry.Key;
            string want = entry.Value;
            Test.Case(key, () => Test.Equal(want, Evaluate(key), $"call {key}"));
        }
    }

    /// <summary>Creates the virtual machine over the compiled fixtures, once for all tests.</summary>
    private static (VirtualMachine Vm, JavaThread Thread) Machine()
    {
        if (_vm is not null && _thread is not null) return (_vm, _thread);

        string classes = Path.Combine(LocateFixtures(), "classes");

        var vm = new VirtualMachine(new VirtualMachineOptions
        {
            ClassSource = new DirectoryClassSource(classes),
            Modules = RuntimeLibrary.Headless,
            StandardOut = Console.Write,
            StandardError = Console.Error.Write,
        });

        _vm = vm;
        _thread = vm.CreateThread("test");
        return (vm, _thread);
    }

    /// <summary>Dispatches one expectation key to the call it names.</summary>
    private static string Evaluate(string key) => key switch
    {
        "arithmetic.17.5" => Int("arithmetic", "(II)I", JavaValue.Int(17), JavaValue.Int(5)),
        "arithmetic.-31.7" => Int("arithmetic", "(II)I", JavaValue.Int(-31), JavaValue.Int(7)),
        "arithmetic.0.0" => Int("arithmetic", "(II)I", JavaValue.Int(0), JavaValue.Int(0)),
        "arithmetic.max.min" => Int("arithmetic", "(II)I",
            JavaValue.Int(int.MaxValue), JavaValue.Int(int.MinValue)),

        "divideEdgeCases" => Int("divideEdgeCases", "()I"),
        "longEdgeCases" => Long("longEdgeCases", "()J"),
        "longArithmetic" => Long("longArithmetic", "(JJ)J",
            JavaValue.Long(0x0123456789abcdefL), JavaValue.Long(-98765432101L)),
        "longCompare.lt" => Int("longCompare", "(JJ)I", JavaValue.Long(-5), JavaValue.Long(900000000000L)),
        "longCompare.gt" => Int("longCompare", "(JJ)I", JavaValue.Long(900000000000L), JavaValue.Long(-5)),
        "longCompare.eq" => Int("longCompare", "(JJ)I", JavaValue.Long(42), JavaValue.Long(42)),

        "doubleMath" => Double("doubleMath", "(D)D", JavaValue.Double(1234.5)),
        "floatToIntEdge" => Int("floatToIntEdge", "()I"),
        "floatCompare.nan" => Int("floatCompare", "(FF)I",
            JavaValue.Float(BitConverter.Int32BitsToSingle(0x7fc00000)), JavaValue.Float(1.0f)),
        "floatCompare.lt" => Int("floatCompare", "(FF)I", JavaValue.Float(1.5f), JavaValue.Float(2.5f)),

        "arraySum" => Int("arraySum", "([I)I", JavaValue.Ref(IntArray(5, -3, 17, 0, 99))),
        "multiArray" => Int("multiArray", "(II)I", JavaValue.Int(7), JavaValue.Int(5)),
        "arrayTypes" => Int("arrayTypes", "()I"),

        "buildString" => Str("buildString", "(I)Ljava/lang/String;", JavaValue.Int(6)),
        "stringOps" => Int("stringOps", "(Ljava/lang/String;)I", JavaValue.Ref(NewString("a banana"))),
        "stringHash" => JavaText.StringHashCode("javax.microedition.lcdui").ToString(),
        "concat" => Str("concat", "(Ljava/lang/String;ICZ)Ljava/lang/String;",
            JavaValue.Ref(NewString("v")), JavaValue.Int(-7), JavaValue.Int('z'), JavaValue.Bool(true)),

        "tableSwitch.3" => Int("tableSwitch", "(I)I", JavaValue.Int(3)),
        "tableSwitch.9" => Int("tableSwitch", "(I)I", JavaValue.Int(9)),
        "lookupSwitch.10000" => Int("lookupSwitch", "(I)I", JavaValue.Int(10000)),
        "lookupSwitch.7" => Int("lookupSwitch", "(I)I", JavaValue.Int(7)),
        "loops" => Int("loops", "(I)I", JavaValue.Int(20)),
        "recursion" => Int("recursion", "(I)I", JavaValue.Int(12)),

        "exceptions.0" => Int("exceptions", "(I)I", JavaValue.Int(0)),
        "exceptions.1" => Int("exceptions", "(I)I", JavaValue.Int(1)),
        "exceptions.2" => Int("exceptions", "(I)I", JavaValue.Int(2)),
        "exceptions.3" => Int("exceptions", "(I)I", JavaValue.Int(3)),
        "exceptions.4" => Int("exceptions", "(I)I", JavaValue.Int(4)),
        "exceptions.9" => Int("exceptions", "(I)I", JavaValue.Int(9)),
        "nestedFinally.0" => Int("nestedFinally", "(I)I", JavaValue.Int(0)),
        "nestedFinally.1" => Int("nestedFinally", "(I)I", JavaValue.Int(1)),

        "virtualDispatch" => Int("virtualDispatch", "()I"),
        "interfaceDispatch" => Int("interfaceDispatch", "()I"),
        "toStringDispatch" => Str("toStringDispatch", "()Ljava/lang/String;"),
        "instanceChecks" => Int("instanceChecks", "()I"),

        "staticState" => Int("staticState", "()I"),

        "vectorTest" => Int("vectorTest", "()I"),
        "hashtableTest" => Int("hashtableTest", "()I"),
        "randomTest.12345" => Long("randomTest", "(J)J", JavaValue.Long(12345)),
        "randomTest.0" => Long("randomTest", "(J)J", JavaValue.Long(0)),

        // Regressions, each pinned to a defect real games hit.
        "singleLetterClass" => Int("singleLetterClass", "()I"),
        "clinitMidExpression" => Str("clinitMidExpression", "()Ljava/lang/String;"),
        "overloadedFieldNames" => Str("overloadedFieldNames", "()Ljava/lang/String;"),
        "subclassOfRuntimeClass" => Int("subclassOfRuntimeClass", "()I"),

        "threadTest" => Int("threadTest", "()I"),

        _ => throw new AssertionException($"no test is wired up for expectation '{key}'"),
    };

    // ---------------------------------------------------------------------------------
    // Invocation helpers
    // ---------------------------------------------------------------------------------

    private static JavaValue Call(string name, string descriptor, params JavaValue[] arguments)
    {
        (VirtualMachine vm, JavaThread thread) = Machine();

        JavaClass type = vm.LoadClass("VmTest");
        JavaMethod method = type.FindMethod(name, descriptor)
                            ?? throw new AssertionException($"VmTest has no method {name}{descriptor}");

        return vm.CallStatic(thread, method, arguments);
    }

    private static string Int(string name, string descriptor, params JavaValue[] arguments) =>
        Call(name, descriptor, arguments).AsInt.ToString();

    private static string Long(string name, string descriptor, params JavaValue[] arguments) =>
        Call(name, descriptor, arguments).AsLong.ToString();

    private static string Double(string name, string descriptor, params JavaValue[] arguments) =>
        JavaText.DoubleToString(Call(name, descriptor, arguments).AsDouble);

    private static string Str(string name, string descriptor, params JavaValue[] arguments) =>
        VirtualMachine.ToHostString(Call(name, descriptor, arguments).Reference as JavaObject) ?? "null";

    private static JavaObject NewString(string value) => Machine().Vm.NewString(value);

    private static JavaObject IntArray(params int[] values)
    {
        JavaArray<int> array = Machine().Vm.NewIntArray(values.Length);
        values.CopyTo(array.Items, 0);
        return array;
    }

    // ---------------------------------------------------------------------------------
    // Fixture discovery
    // ---------------------------------------------------------------------------------

    private static Dictionary<string, string> ReadExpectations(string path)
    {
        var expectations = new Dictionary<string, string>(StringComparer.Ordinal);

        foreach (string line in File.ReadAllLines(path))
        {
            if (line.Length == 0) continue;

            int separator = line.IndexOf('=');
            if (separator <= 0) continue;

            expectations[line[..separator]] = line[(separator + 1)..];
        }

        return expectations;
    }

    /// <summary>
    /// Finds the fixtures folder whether the suite runs from the build output or the repository.
    /// </summary>
    public static string LocateFixtures()
    {
        var directory = new DirectoryInfo(AppContext.BaseDirectory);

        while (directory is not null)
        {
            string candidate = Path.Combine(directory.FullName, "fixtures");
            if (Directory.Exists(candidate) && File.Exists(Path.Combine(candidate, "expected.txt")))
                return candidate;

            string nested = Path.Combine(directory.FullName, "tests", "fixtures");
            if (Directory.Exists(nested)) return nested;

            directory = directory.Parent;
        }

        return Path.Combine(AppContext.BaseDirectory, "fixtures");
    }
}
